<template>
	<div class="min-h-dvh bg-ui-canvas text-ui-ink pb-safe">
		<header class="sticky top-0 z-30 bg-ui-canvas px-5 pt-safe pb-4">
			<div class="app-container-narrow flex items-center gap-3">
				<RouterLink
					:to="{ name: 'Account' }"
					class="flex h-11 w-11 items-center justify-center rounded-full text-primary"
					aria-label="Kembali ke Profile"
				>
					<svg
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7M5 12h14" />
					</svg>
				</RouterLink>
				<h1 class="text-2xl font-bold">Appearance</h1>
			</div>
		</header>
		<main class="app-container-narrow px-5 pt-5 pb-10">
			<div class="relative">
				<span
					id="theme-mode-label"
					class="absolute left-5 -top-2.5 z-10 bg-ui-canvas px-2 text-sm font-medium text-primary"
					>Theme Mode</span
				>
				<button
					id="theme-mode"
					ref="modeTrigger"
					type="button"
					class="flex h-16 w-full items-center justify-between rounded-[1.5rem] border border-primary bg-ui-canvas px-6 text-left text-lg font-medium text-ui-ink"
					aria-labelledby="theme-mode-label theme-mode-value"
					aria-haspopup="dialog"
					:aria-expanded="showModeSheet"
					@click="openModeSheet"
				>
					<span id="theme-mode-value">{{ modeLabel(appearance.mode) }}</span>
					<svg
						class="h-5 w-5 shrink-0 text-ui-muted transition-transform duration-200"
						:class="showModeSheet ? 'rotate-180' : ''"
						viewBox="0 0 24 24"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m6 9 6 6 6-6" />
					</svg>
				</button>
			</div>
			<p
				v-if="!appearance.storageAvailable"
				role="status"
				class="mt-3 text-sm text-ui-muted"
			>
				Tema diterapkan untuk sesi ini. Browser tidak mengizinkan penyimpanan pilihan.
			</p>
			<section
				v-for="group in visibleGroups"
				:key="group.mode"
				class="mt-8"
				:aria-labelledby="group.mode + '-themes'"
			>
				<h2 :id="group.mode + '-themes'" class="text-2xl font-semibold">
					{{ group.label }}
				</h2>
				<p class="mt-1 text-sm text-ui-muted">{{ group.description }}</p>
				<div
					class="scrollbar-hide mt-4 flex gap-4 overflow-x-auto px-1 py-2 snap-x snap-mandatory"
					role="group"
					:aria-label="group.label"
				>
					<button
						v-for="theme in themes.filter((t) => t.mode === group.mode)"
						:key="theme.id"
						type="button"
						:data-theme-choice="theme.id"
						:aria-pressed="selected(theme)"
						:aria-label="theme.name + (selected(theme) ? ', terpilih' : '')"
						class="appearance-swatch relative w-48 shrink-0 snap-start rounded-[1.75rem] border-2 p-5 text-left"
						:style="swatchStyle(theme)"
						@click="chooseTheme(theme)"
					>
						<span
							class="block text-xl font-semibold"
							:style="{ color: theme.primary }"
							>{{ theme.name }}</span
						>
						<span class="mt-5 grid grid-cols-3 gap-2" aria-hidden="true">
							<span
								class="flex h-10 items-center justify-center rounded-xl text-lg font-semibold"
								:style="{ background: theme.primary, color: theme.onPrimary }"
								>A</span
							>
							<span
								class="flex h-10 items-center justify-center rounded-xl text-lg font-semibold"
								:style="{ background: theme.raised, color: theme.ink }"
								>A</span
							>
							<span
								class="flex h-10 items-center justify-center rounded-xl text-lg font-semibold"
								:style="{ background: theme.muted, color: theme.surface }"
								>A</span
							>
							<span
								class="flex h-10 items-center justify-center rounded-xl text-lg font-semibold"
								:style="{ background: theme.action, color: theme.onPrimary }"
								>A</span
							>
						</span>
						<span
							v-if="selected(theme)"
							class="absolute bottom-5 right-5"
							:style="{ color: theme.primary }"
							aria-hidden="true"
							><svg
								viewBox="0 0 24 24"
								class="h-7 w-7"
								fill="none"
								stroke="currentColor"
								stroke-width="2"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<circle cx="12" cy="12" r="10" />
								<path d="m7 12 3 3 7-7" /></svg
						></span>
					</button>
				</div>
			</section>
		</main>

		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200 ease-out"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150 ease-in"
				leave-to-class="opacity-0"
			>
				<div
					v-if="showModeSheet"
					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="closeModeSheet"
					@keydown.esc="closeModeSheet"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-300 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-200 ease-in"
						leave-to-class="translate-y-full"
					>
						<section
							v-if="showModeSheet"
							role="dialog"
							aria-modal="true"
							aria-labelledby="mode-sheet-title"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.5rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2
								id="mode-sheet-title"
								class="mb-2 text-center text-xl font-semibold text-ui-heading"
							>
								Pilih Theme Mode
							</h2>
							<button
								v-for="option in modeOptions"
								:key="option.value"
								type="button"
								class="flex w-full items-center gap-4 border-b border-ui-line-gray-100 py-4 text-left last:border-b-0"
								:aria-pressed="appearance.mode === option.value"
								@click="selectMode(option.value)"
							>
								<span
									class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2"
									:class="
										appearance.mode === option.value
											? 'border-ui-action'
											: 'border-ui-line-gray-300'
									"
								>
									<span
										v-if="appearance.mode === option.value"
										class="h-3 w-3 rounded-full bg-ui-action"
									/>
								</span>
								<span class="text-lg font-semibold text-ui-heading">{{
									option.label
								}}</span>
							</button>
						</section>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { appearance, themes, setAppearance } from '../composables/appearance'

const showModeSheet = ref(false)
const modeTrigger = ref(null)
const modeOptions = [
	{ value: 'light', label: 'Light' },
	{ value: 'dark', label: 'Dark' },
	{ value: 'system', label: 'System' },
]
const groups = [
	{ mode: 'light', label: 'Light Themes', description: 'Pilihan tema untuk mode terang.' },
	{ mode: 'dark', label: 'Dark Themes', description: 'Pilihan tema untuk mode gelap.' },
]
const visibleGroups = computed(() =>
	appearance.value.mode === 'system'
		? groups
		: groups.filter((group) => group.mode === appearance.value.mode),
)
function modeLabel(mode) {
	return modeOptions.find((option) => option.value === mode)?.label || 'System'
}
async function openModeSheet() {
	showModeSheet.value = true
	await nextTick()
	document
		.querySelector('#mode-sheet-title')
		?.closest('section')
		?.querySelector('[aria-pressed="true"]')
		?.focus()
}
function closeModeSheet() {
	showModeSheet.value = false
	nextTick(() => modeTrigger.value?.focus())
}
function selectMode(mode) {
	setAppearance({ mode })
	closeModeSheet()
}
function selected(theme) {
	return appearance.value[theme.mode + 'Theme'] === theme.id
}
function chooseTheme(theme) {
	// Keep System selected when configuring its day/night pair. In manual mode,
	// clicking a card also activates that card's mode for immediate feedback.
	setAppearance({
		[theme.mode + 'Theme']: theme.id,
		mode: appearance.value.mode === 'system' ? 'system' : theme.mode,
	})
}
function swatchStyle(theme) {
	return {
		'--swatch-surface': theme.surface,
		'--swatch-ink': theme.ink,
		borderColor: selected(theme) ? theme.primary : theme.line,
	}
}
function onEscape(event) {
	if (event.key === 'Escape' && showModeSheet.value) closeModeSheet()
}
onMounted(() => window.addEventListener('keydown', onEscape))
onBeforeUnmount(() => window.removeEventListener('keydown', onEscape))
</script>
